using System.Collections;
using OcctSharp.ModelingResults;
using OcctSharp.Tests.Shared;
namespace OcctSharp.Runtime.Tests;
public sealed class ModelingResultTests {
 [Fact]public void CoincidentIndependentInputsRetainMultipleSourcePathsWithoutPickingAFace(){using var first=ShapeFactory.CreateBox(4,5,6);using var duplicate=ShapeFactory.CreateBox(4,5,6);using var compound=ShapeFactory.CreateCompound([first,duplicate]);using var raw=ShapeFactory.CreateBox(4,5,6);using var tool=raw.Transformed(ShapeTransform.CreateTranslationAndRotationZ(2,1,1,0));using var result=ModelingResultComputations.Section(compound,tool);Assert.True(result.IsDone,result.Message);Assert.Contains(result.Sources,x=>x.State==ModelingSourceState.Multiple&&x.SdkPathCount>1);foreach(var link in result.Sources.Where(x=>x.State==ModelingSourceState.Multiple)){Assert.Equal(0,link.SourceTopologyOrdinal);Assert.Equal(0,link.SecondSourceTopologyOrdinal);}}
 [Fact]public void GeometryToModelingResultsAndRealStepIgesReadback()=>BatchBGModelingWorkflow.Run();
 [Fact]public void SectionAncestorsBelongToExactIndependentInputDomain(){using var a=ShapeFactory.CreateBox(4,5,6);using var raw=ShapeFactory.CreateBox(4,5,6);using var b=raw.Transformed(ShapeTransform.CreateTranslationAndRotationZ(2,1,1,0));using var result=ModelingResultComputations.Section(a,b,new(Approximation:true));Assert.True(result.IsDone,result.Message);Assert.True(result.ResultEdgeCount>0);Assert.Contains(result.Sources,x=>x.State==ModelingSourceState.Exact);foreach(var l in result.Sources){if(l.State==ModelingSourceState.Exact){Assert.Equal(1,l.SdkPathCount);using var left=result.CopyInput(0,l.SourceTopologyOrdinal);using var right=result.CopyInput(1,l.SecondSourceTopologyOrdinal);using var edge=result.CopyResultTopology(l.ResultTopologyOrdinal);Assert.Equal(ShapeKind.Face,left.Kind);Assert.Equal(ShapeKind.Face,right.Kind);Assert.Equal(ShapeKind.Edge,edge.Kind);}else{Assert.Equal(0,l.SourceTopologyOrdinal);Assert.Equal(0,l.SecondSourceTopologyOrdinal);}}using var copy=result.CopyResult();var snapshot=result.Sources;a.Dispose();b.Dispose();result.Dispose();Assert.True(copy.IsValid);Assert.NotEmpty(snapshot);Assert.Throws<ObjectDisposedException>(()=>result.CopyResult());}
 [Fact]public void SeparatedSectionIsCompletedWithNoHits(){using var a=ShapeFactory.CreateBox(2,2,2);using var raw=ShapeFactory.CreateBox(2,2,2);using var b=raw.Transformed(ShapeTransform.CreateTranslationAndRotationZ(20,0,0,0));using var result=ModelingResultComputations.Section(a,b);Assert.True(result.IsDone,result.Message);Assert.Equal(0,result.ResultEdgeCount);Assert.Empty(result.Sources);}
 [Fact]public void CommonTangentSectionDoesNotInventAnAncestor(){using var a=ShapeFactory.CreateBox(2,2,2);using var raw=ShapeFactory.CreateBox(2,2,2);using var b=raw.Transformed(ShapeTransform.CreateTranslationAndRotationZ(2,0,0,0));using var result=ModelingResultComputations.Section(a,b);Assert.True(result.IsDone,result.Message);Assert.True(result.ResultEdgeCount>0);Assert.Contains(result.Sources,x=>x.State==ModelingSourceState.Missing);Assert.All(result.Sources.Where(x=>x.State!=ModelingSourceState.Exact),x=>{Assert.Equal(0,x.SourceTopologyOrdinal);Assert.Equal(0,x.SecondSourceTopologyOrdinal);});}
 [Theory][InlineData(0,false)][InlineData(2,true)]public void OffsetExplicitConfigurationProducesIndependentValidGeometry(int join,bool approximation){using var wire=BatchBGModelingWorkflow.Square();using var result=ModelingResultComputations.Offset([wire],.5,new(Join:join,Approximation:approximation));Assert.True(result.IsDone,result.Message);using var shape=result.CopyResult();using var reference=FreeformAuthoring.OffsetPlanarWire(wire,.5,join:join==0?PlanarOffsetJoin.Arc:PlanarOffsetJoin.Intersection);Assert.Equal(reference.GetBoundingBox().Minimum.X,shape.GetBoundingBox().Minimum.X,6);wire.Dispose();result.Dispose();Assert.True(shape.IsValid);}
 [Fact]public void OpenOffsetAndFaceOffsetUseInitializedPrivateInputs(){using var open=ShapeFactory.CreatePolygonWire([new(0,0,0),new(4,0,0),new(4,3,0)]);using var result=ModelingResultComputations.Offset([open],.2,new(OpenResult:true));Assert.True(result.IsDone,result.Message);using var shape=result.CopyResult();Assert.True(shape.IsValid);using var wire=BatchBGModelingWorkflow.Square();using var face=ShapeFactory.CreatePlanarFace(wire);using var fromFace=ModelingResultComputations.Offset([face],.3);Assert.True(fromFace.IsDone,fromFace.Message);}
 [Fact]public void NonplanarOffsetRetainsFailureAndPublishesNoPartialTopology(){using var wire=ShapeFactory.CreatePolygonWire([new(0,0,0),new(4,0,0),new(4,3,1),new(0,3,0)],true);using var result=ModelingResultComputations.Offset([wire],.3);Assert.False(result.IsDone);Assert.Equal(0,result.ResultTopologyCount);Assert.Throws<InvalidOperationException>(()=>result.CopyResult());using var source=result.CopyInput(0);Assert.True(source.IsValid);}
 [Theory][InlineData(true,false)][InlineData(false,true)]public void LoftSnapshotAndGeometryAgreeWithExistingBuilderWithoutChangingInputs(bool ruled,bool smoothing){using var a=BatchBGModelingWorkflow.Square();using var b=BatchBGModelingWorkflow.Square(3);using var c=BatchBGModelingWorkflow.Square(6);var old=a.GetBoundingBox();using var result=ModelingResultComputations.Loft([a,b,c],new(Solid:true,Ruled:ruled,Smoothing:smoothing,Weight1:2,Weight2:3,Weight3:4));Assert.True(result.IsDone,result.Message);var config=result.LoftConfiguration!;Assert.False(config.MutableInput);Assert.Equal(smoothing,config.Smoothing);Assert.Equal(2,config.Weight1);Assert.Equal(3,config.Weight2);Assert.Equal(4,config.Weight3);using var shape=result.CopyResult();using var reference=ShapeFactory.CreateLoft([a,b,c],makeSolid:true,ruled:ruled);Assert.Equal(reference.InspectProperties(InspectionPropertyKind.Volume).Mass,shape.InspectProperties(InspectionPropertyKind.Volume).Mass,6);Assert.Equal(old,a.GetBoundingBox());Assert.NotEmpty(result.Sources);a.Dispose();b.Dispose();c.Dispose();result.Dispose();Assert.True(shape.IsValid);Assert.Equal(96,shape.InspectProperties(InspectionPropertyKind.Volume).Mass,6);}
 [Fact]public void InvalidProfilesAndBudgetsFailBeforePublishing(){using var wire=BatchBGModelingWorkflow.Square();Assert.ThrowsAny<Exception>(()=>ModelingResultComputations.Loft([wire]));Assert.ThrowsAny<Exception>(()=>ModelingResultComputations.Loft([wire,wire],new(Weight1:double.NaN)));Assert.ThrowsAny<Exception>(()=>ModelingResultComputations.Offset([wire],double.NaN));Assert.ThrowsAny<Exception>(()=>ModelingResultComputations.Offset([wire],.1,new(Join:1)));Assert.ThrowsAny<Exception>(()=>ModelingResultComputations.Section(wire,wire,new(FuzzyTolerance:0)));var endless=new Endless(wire);Assert.Throws<ArgumentOutOfRangeException>(()=>ModelingResultComputations.Loft(endless));Assert.Equal(65,endless.Yielded);Assert.True(endless.Disposed);}
 [Fact]public void DifferentPrivateResultsHaveDifferentDomainIdentities(){using var a=BatchBGModelingWorkflow.Square();using var b=BatchBGModelingWorkflow.Square(3);using var first=ModelingResultComputations.Loft([a,b],new(Ruled:true));using var second=ModelingResultComputations.Loft([a,b],new(Ruled:true));Assert.NotEqual(first.Identity,second.Identity);Assert.Throws<ArgumentOutOfRangeException>(()=>first.CopyResultTopology(0));Assert.ThrowsAny<Exception>(()=>first.CopyInput(0,int.MaxValue));}
 sealed class Endless(Shape source):IEnumerable<Shape>{public int Yielded;public bool Disposed;public IEnumerator<Shape> GetEnumerator(){try{while(true){++Yielded;yield return source;}}finally{Disposed=true;}}IEnumerator IEnumerable.GetEnumerator()=>GetEnumerator();}
}
